class NumberWordFormatter:
    NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
    NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                   "EIGHTEEN", "NINETEEN"]
    NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
    NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
    NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def __init__(self):
        pass

    def format(self, x):
        if x is not None:
            return self.format_string(str(x))
        else:
            return ""

    def format_string(self, x):
        lstr, rstr = (x.split('.') + [''])[:2]
        lstrrev = self._reverse_padded_integer_part(lstr)
        a = [''] * 5

        lm = self._build_left_string(lstrrev, a)

        xs = f"AND CENTS {self.trans_two(rstr)} " if rstr else ""
        if not lm.strip():
            return "ZERO ONLY"
        else:
            return f"{lm.strip()} {xs}ONLY"

    def _reverse_padded_integer_part(self, lstr):
        lstrrev = lstr[::-1]
        if len(lstrrev) % 3 == 1:
            lstrrev += "00"
        elif len(lstrrev) % 3 == 2:
            lstrrev += "0"
        return lstrrev

    def _build_left_string(self, lstrrev, a):
        lm = ""
        for i in range(len(lstrrev) // 3):
            a[i] = lstrrev[3 * i:3 * i + 3][::-1]
            if a[i] != "000":
                lm = self.trans_three(a[i]) + " " + self.parse_more(i) + " " + lm
            else:
                lm += self.trans_three(a[i])
        return lm

    def trans_two(self, s):
        s = s.zfill(2)
        if s[0] == "0":
            return self._get_number_by_index(int(s[-1]))
        elif s[0] == "1":
            return self._get_teens_by_index(int(s) - 10)
        elif s[1] == "0":
            return self._get_tens_by_index(int(s[0]) - 1)
        else:
            return self._get_tens_by_index(int(s[0]) - 1) + " " + self._get_number_by_index(int(s[-1]))

    def trans_three(self, s):
        if s[0] == "0":
            return self.trans_two(s[1:])
        elif s[1:] == "00":
            return f"{self._get_number_by_index(int(s[0]))} HUNDRED"
        else:
            return f"{self._get_number_by_index(int(s[0]))} HUNDRED AND {self.trans_two(s[1:])}"

    def parse_more(self, i):
        return self._get_numeric_more_by_index(i)

    @classmethod
    def _get_number_by_index(cls, index):
        return cls.NUMBER[index]

    @classmethod
    def _get_teens_by_index(cls, index):
        return cls.NUMBER_TEEN[index]

    @classmethod
    def _get_tens_by_index(cls, index):
        return cls.NUMBER_TEN[index]

    @classmethod
    def _get_numeric_more_by_index(cls, index):
        return cls.NUMBER_MORE[index]
